CREATE TABLE export_attempt_items(
 job_id TEXT NOT NULL REFERENCES export_attempts(job_id) ON DELETE CASCADE,
 index_id TEXT NOT NULL,
 ordinal INTEGER NOT NULL CHECK(ordinal>=0),
 outcome TEXT NOT NULL DEFAULT 'pending' CHECK(outcome IN('pending','completed','skipped','failed','cancelled')),
 PRIMARY KEY(job_id,index_id,ordinal)
) STRICT;
-- Historical attempts have no reliable per-attempt evidence. Do not infer it
-- from the current plan, whose files may have been regenerated by later attempts.
